{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "MEDIUM",
      "explanation": "The `block_public_acls` argument is missing from the `aws_s3_bucket_public_access_block` resource. Without this setting, existing or new public Access Control Lists (ACLs) on the bucket are not blocked, potentially allowing unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n  block_public_acls       = true\n}",
  "fix_summary": "Added the missing `block_public_acls = true` attribute to the `aws_s3_bucket_public_access_block` resource to ensure all four public access blocking settings are explicitly enabled."
}
